// The whole point of routing every send through this sub-workflow: a workflow
// author cannot forget the consent check, because they never touch SMTP.
const rows = $input.first().json.data?.consentRecords || [];
const latest = rows[0];
const person = $('Get person').first().json.data?.person || {};
const email  = person.emails?.primaryEmail;

if (!email)                       return [{ json: { send:false, reason:'no_email' }}];
if (!latest)                      return [{ json: { send:false, reason:'no_consent_record' }}];
if (latest.status !== 'OPTED_IN') return [{ json: { send:false, reason:`consent_${latest.status}` }}];

// Second gate, only when LIVE_MAIL_ALLOWLIST is set. An empty list means
// "consent is enough" — production. A non-empty list is how a live Gmail
// demo on a laptop cannot accidentally SMTP a seeded .example.com address
// or a prove_workflows fake domain. The refusal is logged the same way as
// a consent block, so it shows up on the person, not only in n8n.
const allow = String($env.LIVE_MAIL_ALLOWLIST || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const dest = String(email).trim().toLowerCase();
if (allow.length && !allow.includes(dest)) {
  return [{ json: { send:false, reason:'not_on_allowlist' }}];
}

return [{ json: {
  send: true, email,
  firstName: person.name?.firstName || '',
  personId: $('When called').first().json.personId,
  templateKey: $('When called').first().json.templateKey,
  mergeData: $('When called').first().json.mergeData || {},
}}];

// Templates live here, in version control, not in a vendor UI nobody can diff.
const TEMPLATES = {
  lead_ack: {
    subject: 'Thanks for getting in touch, {{firstName}}',
    body: `<p>Hi {{firstName}},</p>
<p>Thanks for reaching out to Aspire. One of our security specialists
will be in touch within one business day.</p>
<p>— Aspire Tech</p>`,
  },
  renewal_60d: {
    subject: 'Your {{serviceLine}} renewal — {{renewalDate}}',
    body: `<p>Hi {{firstName}},</p>
<p>Your {{serviceLine}} subscription renews on {{renewalDate}}.
We will reach out shortly to confirm.</p>
<p>— Aspire Tech</p>`,
  },
  appt_reminder_24h: {
    subject: 'Reminder: {{appointmentType}} tomorrow',
    body: `<p>Hi {{firstName}},</p>
<p>A reminder of your {{appointmentType}} at {{scheduledAt}}.</p>
<p>{{meetingUrl}}</p>`,
  },
  nurture_1: {
    subject: 'Following up on your enquiry, {{firstName}}',
    body: `<p>Hi {{firstName}},</p>
<p>You got in touch with us a few days ago and I wanted to make sure your
question did not get lost.</p>
<p>If it would help to talk it through, just reply to this email and we will
find a time.</p>
<p>— Aspire Tech</p>`,
  },
  nurture_2: {
    subject: 'Anything we can help with, {{firstName}}?',
    body: `<p>Hi {{firstName}},</p>
<p>Still happy to help with what you asked about. Most people come to us
with one of three things: a CMMC assessment deadline, a security monitoring
gap, or training that needs to actually change behaviour.</p>
<p>If any of those is on your list, reply and tell me which.</p>
<p>— Aspire Tech</p>`,
  },
  nurture_3: {
    subject: 'Last note from me, {{firstName}}',
    body: `<p>Hi {{firstName}},</p>
<p>I do not want to keep filling your inbox, so this is my last note about
your enquiry.</p>
<p>If the timing is wrong, that is completely fine — reply whenever it
changes and we will pick it up.</p>
<p>— Aspire Tech</p>`,
  },
};

const d = $input.first().json;
const t = TEMPLATES[d.templateKey];
if (!t) throw new Error(`Unknown templateKey: ${d.templateKey}`);

const vars = { firstName: d.firstName, ...d.mergeData };
const fill = (s) => s.replace(/\{\{(\w+)\}\}/g, (_, k) => vars[k] ?? '');

return [{ json: { ...d, subject: fill(t.subject), html: fill(t.body) } }];
